#include <iostream>
#include <string>

class Counter {
public:
    Counter() : count(0) {}

    void increment() const {
        // This method is const, but count can still be modified due to 'mutable'
        count++;
    }

    int getCount() const {
        return count;
    }

private:
    mutable int count;  // 'mutable' allows modification even in const methods
};

int main() {
    Counter counter;
    counter.increment();
    counter.increment();

    std::cout << "Counter: " << counter.getCount() << std::endl;
    return 0;
}
