    // Printing second complex number
    cout << "Complex number 2 : " << 
             C2.real << " + i" << 
             C2.imaginary << endl;

    // For Storing the sum
    Complex C3;

    // Calling addComp() method
    C3 = C3.addComp(C1, C2);

    // Printing the sum
