    // Value to search
    int key = 8;

    // Searching the key in the vector v
    int i = linearSearch(v, key, 0);

    // Checking if element is found or not
    if (i != -1) {
        cout << key << " Found at Position: "
          << i + 1;
    } else {
        cout << key << " NOT found.";
    }

    return 0;
}
