#include<iostream>
#include<cmath>
using namespace std;

int determinant(int matrix[4][4], int n){
        int det = 0;
        int submatrix[4][4];

        if(n == 1){
                return matrix[0][0];
        }
        else if(n == 2){
                return ((matrix[0][0] * matrix[1][1]) - (matrix[1][0] * matrix[0][1]));
        }
        else{
                for(int x = 0; x < n; x++){
                        int subi = 0;
                        for(int i = 1; i < n; i++){
                                int subj = 0;
                                for(int j = 0; j < n; j++){
                                        if(j == x){
                                                continue;
                                        }
                                        submatrix[subi][subj] = matrix[i][j];
                                        subj++;
                                }
                                subi++;
                        }
                        det = det + (pow(-1, x) * matrix[0][x] * determinant(submatrix, n-1));
                }
        }
        return det;
}

int main(){
        int matrix[4][4] = {{1, 0, 2, -1},
                                        {3, 0, 0, 5},
                                        {2, 1, 4, -3},
                                        {1, 0, 5, 0}};
        int n = 4;
        int det = determinant(matrix, n);
        cout<<"Determinant: "<<det<<endl;
        return 0;
}
